const CSS=".card{box-sizing:border-box;width:100%;height:100%;min-width:0;min-height:0;display:flex;flex-direction:column;padding:12px;overflow:hidden;color:var(--ink);font:13px/1.35 -apple-system,BlinkMacSystemFont,\"PingFang SC\",\"Microsoft YaHei\",sans-serif}\n.card *{box-sizing:border-box}\n.card[data-size=\"6x3\"]{padding:10px 14px}\n.card[data-size=\"6x6\"]{padding:16px 18px;font-size:14px}\n.view{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;gap:8px}\n.hd{flex:none;display:flex;align-items:center;justify-content:space-between;gap:8px;min-width:0}\n.ttl{min-width:0}\nh1,h2,p,ul{margin:0}\nh1{font-size:15px;line-height:1.25;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.card[data-size=\"6x6\"] h1{font-size:19px}\n.ht{flex:1;min-width:0}\n.sub{font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.card button{font:inherit;color:inherit;cursor:pointer}\n.btn{display:inline-flex;align-items:center;justify-content:center;min-height:30px;padding:0 12px;border-radius:999px;border:1px solid var(--line);background:var(--panel-paper);color:var(--ink);font-weight:600;white-space:nowrap;flex:none}\n.btn.pri{background:var(--accent);color:var(--on-accent);border-color:transparent}\n.btn:disabled{opacity:.55;cursor:default}\n.btn.grow{flex:1}\n.card button:focus-visible,.inp:focus-visible{outline:2px solid var(--accent);outline-offset:2px}\n.list,.body{flex:1;min-height:0;min-width:0;overflow-y:auto;overflow-x:hidden;display:flex;flex-direction:column;gap:6px;scrollbar-width:thin;padding-right:2px}\n.row{flex:none;display:grid;grid-template-columns:minmax(0,1fr) auto;grid-template-areas:\"body done\" \"due due\";gap:3px 8px;align-items:center;padding:8px 10px;border-radius:12px;background:var(--soft);border:1px solid var(--line)}\n.row.st-over{box-shadow:inset 4px 0 0 var(--accent-alt)}\n.row.st-today{box-shadow:inset 4px 0 0 var(--accent)}\n.row.hl{animation:pulse 1.4s ease-out}\n@keyframes pulse{0%{box-shadow:0 0 0 3px var(--accent)}100%{box-shadow:0 0 0 0 transparent}}\n@media (prefers-reduced-motion:reduce){.row.hl{animation:none}}\n.rbody{grid-area:body;min-width:0;display:flex;flex-direction:column;align-items:flex-start;gap:1px;padding:0;border:0;background:none;text-align:left}\n.rname{max-width:100%;font-weight:650;font-size:13.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.rmeta{max-width:100%;font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.rdue{grid-area:due;min-width:0;display:flex;flex-wrap:wrap;align-items:center;gap:2px 6px;font-size:11.5px}\n.dnext{min-width:0;color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.chip{flex:none;font-size:11px;padding:1px 7px;border-radius:999px;border:1px solid var(--line);background:var(--panel-paper);color:var(--ink);white-space:nowrap}\n.rdone{grid-area:done}\n.card[data-size=\"3x3\"] .rmeta{display:none}\n.card[data-size=\"6x3\"] .row,.card[data-size=\"6x6\"] .row{grid-template-columns:minmax(0,1.2fr) minmax(0,1fr) auto;grid-template-areas:\"body due done\";gap:8px 12px}\n.card[data-size=\"6x3\"] .rdue,.card[data-size=\"6x6\"] .rdue{flex-direction:column;align-items:flex-start;flex-wrap:nowrap}\n.card[data-size=\"6x6\"] .row{padding:11px 14px}\n.card[data-size=\"6x6\"] .rname{font-size:15px}\n.card[data-size=\"6x6\"] .rmeta,.card[data-size=\"6x6\"] .rdue{font-size:12.5px}\n.empty{flex:1;min-height:0;display:flex;flex-direction:column;justify-content:center;gap:8px}\n.e1{font-weight:650;font-size:14px}\n.e2{font-size:11.5px;color:var(--muted)}\n.card[data-size=\"3x3\"] .e2{display:none}\n.sugs{display:flex;flex-wrap:wrap;gap:6px}\n.sug{min-height:28px;padding:0 10px;border-radius:999px;border:1px dashed var(--line);background:var(--panel-paper);color:var(--ink);font-size:12px}\n.err{flex:none;font-size:12px;font-weight:600;color:var(--ink);padding:6px 8px;border-radius:8px;background:var(--soft);border:1px solid var(--accent-alt)}\n\n.dsum{flex:none;padding:10px 12px;border-radius:12px;background:var(--soft);border:1px solid var(--line);display:flex;flex-direction:column;gap:3px}\n.dsum.st-over{box-shadow:inset 4px 0 0 var(--accent-alt)}\n.dsum.st-today{box-shadow:inset 4px 0 0 var(--accent)}\n.dlab{font-size:11px;color:var(--muted)}\n.dbig{font-size:17px;font-weight:700;line-height:1.25}\n.card[data-size=\"3x3\"] .dbig,.card[data-size=\"3x6\"] .dbig{font-size:15px}\n.card[data-size=\"6x6\"] .dbig{font-size:22px}\n.dline{display:flex;flex-wrap:wrap;align-items:center;gap:4px 8px}\n.dmeta{font-size:11.5px;color:var(--muted)}\n.sec{flex:none;margin-top:4px;font-size:12px;font-weight:650;color:var(--muted)}\n.hist{list-style:none;padding:0;display:flex;flex-direction:column;flex:none}\n.hist li{display:flex;align-items:center;justify-content:space-between;gap:8px;min-height:32px;padding:0 2px;border-bottom:1px solid var(--line);font-size:12.5px}\n.hist li.none{color:var(--muted);border-bottom:0}\n.x{flex:none;width:28px;height:28px;border-radius:50%;border:1px solid var(--line);background:var(--panel-paper);color:var(--ink);font-size:16px;line-height:1;display:inline-flex;align-items:center;justify-content:center;padding:0}\n.bfrow{flex:none;display:flex;gap:8px;align-items:center}\n.bfrow .inp{flex:1;min-width:0}\n.ft{flex:none;display:flex;gap:6px;align-items:center}\n.ft.wrap{flex-wrap:wrap}\n.ft.wrap .btn{flex:1}\n.ask{flex:0 0 100%;font-size:12.5px;font-weight:600}\n.fld{flex:none;display:flex;flex-direction:column;gap:4px;min-width:0}\n.lab{font-size:11.5px;font-weight:600;color:var(--muted)}\n.hint{font-size:11px;color:var(--muted)}\n.inp{width:100%;min-width:0;min-height:32px;padding:4px 8px;border-radius:9px;border:1px solid var(--line);background:var(--panel-paper);color:var(--ink);font:inherit}\n.ivrow{display:flex;align-items:center;gap:6px}\n.ivrow .num{flex:0 0 72px;width:72px}\n.ivrow select{flex:1}\n.card[data-size=\"6x3\"] .body,.card[data-size=\"6x6\"] .body{max-width:520px}\n";
function p2(n){return String(n).padStart(2,'0');}
function unitName(u){return u==='week'?'周':u==='month'?'个月':'天';}
function parseD(s){var a=String(s).split('-').map(Number);return new Date(a[0],a[1]-1,a[2]);}
function fmtD(d){return d.getFullYear()+'-'+p2(d.getMonth()+1)+'-'+p2(d.getDate());}
function addIv(s,n,u){
  var d=parseD(s);
  if(u==='month'){
    var dom=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+n);
    var last=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();
    d.setDate(Math.min(dom,last));
  }else{d.setDate(d.getDate()+n*(u==='week'?7:1));}
  return fmtD(d);
}
function diffDays(a,b){return Math.round((parseD(a)-parseD(b))/86400000);}
function shortD(s){var d=parseD(s);return (d.getMonth()+1)+'月'+d.getDate()+'日';}
function showD(s,today,wk){
  var d=parseD(s);
  var y=d.getFullYear()!==parseD(today).getFullYear()?d.getFullYear()+'年':'';
  return y+shortD(s)+(wk?' 周'+'日一二三四五六'.charAt(d.getDay()):'');
}
function nowHM(){var d=new Date();return p2(d.getHours())+':'+p2(d.getMinutes());}
function recKey(r){return r.date+' '+(r.time||'00:00');}
function recText(r){return shortD(r.date)+(r.time?' '+r.time:'');}
function lastRec(c){
  var b=null;
  (c.history||[]).forEach(function(r){if(!b||recKey(r)>recKey(b))b=r;});
  return b;
}
function freq(c){
  if(c.n===1)return c.unit==='week'?'每周':c.unit==='month'?'每月':'每天';
  return '每 '+c.n+' '+unitName(c.unit);
}
function info(c,today){
  var last=lastRec(c);
  if(!last)return {st:'new',last:null,next:null,diff:null,doneToday:false};
  var next=addIv(last.date,c.n,c.unit);
  var diff=diffDays(next,today);
  var st=diff<0?'over':diff===0?'today':diff<=3?'soon':'ok';
  return {st:st,last:last,next:next,diff:diff,doneToday:last.date===today};
}
function chipText(i){
  if(i.st==='new')return '未记录';
  if(i.st==='over')return '逾期 '+(-i.diff)+' 天';
  if(i.st==='today')return '今天该做';
  if(i.doneToday)return '今天已完成';
  return i.diff===1?'明天':i.diff+' 天后';
}
function sortedRows(list,today){
  var a=list.map(function(c,ix){return {c:c,ix:ix,i:info(c,today)};});
  a.sort(function(x,y){
    if(!x.i.next&&!y.i.next)return x.ix-y.ix;
    if(!x.i.next)return 1;
    if(!y.i.next)return -1;
    if(x.i.next!==y.i.next)return x.i.next<y.i.next?-1:1;
    return x.ix-y.ix;
  });
  return a;
}
function kids(a){return a.filter(Boolean);}

function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day}=ctx;
  const today=day();
  const size=ctx.size||root.getAttribute('data-size')||'3x3';
  const narrow=size==='3x3'||size==='3x6';
  const chores=Array.isArray(state&&state.chores)?state.chores:[];
  const BASE={hl:null,err:null,confirm:null,bf:null,saving:false};
  let listEl=null;
  function nav(patch){Object.assign(ui,BASE,patch);redraw();}
  function patchChore(id,fn){
    return update(function(s){
      return Object.assign({},s,{chores:(s.chores||[]).map(function(c){return c.id===id?fn(c):c;})});
    });
  }
  function fail(e){ui.err='保存失败：'+((e&&e.message)||'请重试');ui.saving=false;redraw();}
  function addRecord(id,rec){
    ui.err=null;
    return patchChore(id,function(c){
      var h=c.history||[];
      var dup=h.some(function(r){return r.date===rec.date&&(r.time||'')===(rec.time||'');});
      return dup?c:Object.assign({},c,{history:h.concat([rec])});
    }).catch(fail);
  }
  function complete(id){ui.hl=id;addRecord(id,{id:uid(),date:day(),time:nowHM()});}
  function errBox(){return ui.err?el('p',{class:'err',role:'alert'},'⚠ '+ui.err):null;}
  function backHead(title,patch){
    return el('div',{class:'hd'},
      el('button',{type:'button',class:'btn back','aria-label':'返回',onclick:function(){nav(patch);}},'‹ 返回'),
      el('h1',{class:'ht'},title));
  }
  function chipEl(i){
    const mark=i.st==='over'?'⚠ ':i.st==='today'?'● ':(i.doneToday?'✓ ':'');
    return el('span',{class:'chip'},mark+chipText(i));
  }
  function sugs(pick){
    return el('div',{class:'sugs'},...['洗床单','打扫卫生','清理冰箱'].map(function(t){
      return el('button',{type:'button',class:'sug',onclick:function(){pick(t);}},t);
    }));
  }
  function startAdd(name){nav({view:'form',sel:null,draft:{name:name||'',n:'',unit:'day',date:''}});}


  function row(r){
    const c=r.c,i=r.i;
    const meta=freq(c)+(i.last?' · 上次 '+recText(i.last):' · 还没做过');
    const due=i.next?'下次 '+showD(i.next,today,!narrow):'下次：完成后显示';
    return el('div',{class:'row st-'+i.st+(ui.hl===c.id?' hl':'')},
      el('button',{type:'button',class:'rbody','aria-label':'查看 '+c.name+' 详情',onclick:function(){nav({view:'detail',sel:c.id});}},
        el('span',{class:'rname'},c.name),
        el('span',{class:'rmeta'},meta)),
      el('div',{class:'rdue'},el('span',{class:'dnext'},due),chipEl(i)),
      el('button',{type:'button',class:'btn pri rdone','aria-label':'完成 '+c.name,onclick:function(){complete(c.id);}},'完成'));
  }

  function listView(){
    const rows=sortedRows(chores,today);
    const nOver=rows.filter(function(r){return r.i.st==='over';}).length;
    const nToday=rows.filter(function(r){return r.i.st==='today';}).length;
    let sub;
    if(!chores.length)sub='还没有家务项';
    else{
      const parts=[];
      if(nOver)parts.push(nOver+' 项逾期');
      if(nToday)parts.push(nToday+' 项今天该做');
      sub=parts.length?parts.join(' · '):'暂无待做 · 共 '+chores.length+' 项';
    }
    const head=el('div',{class:'hd'},
      el('div',{class:'ttl'},el('h1',{},'家务记录'),el('p',{class:'sub'},sub)),
      el('button',{type:'button',class:'btn pri addbtn','aria-label':'添加家务',onclick:function(){startAdd('');}},'＋ 添加'));
    const body=rows.length?rows.map(row):[el('div',{class:'empty'},
      el('p',{class:'e1'},'还没有家务项'),
      el('p',{class:'e2'},'添加后设定多久做一次，点「完成」记下时间，这里会显示下次日期。'),
      sugs(function(t){startAdd(t);}))];
    listEl=el('div',{class:'list'},...body);
    listEl.addEventListener('scroll',function(){ui.scroll=listEl.scrollTop;});
    return el('div',{class:'view'},...kids([head,errBox(),listEl]));
  }

  function detailView(c){
    const i=info(c,today);
    const hist=(c.history||[]).slice().sort(function(a,b){return recKey(a)<recKey(b)?1:recKey(a)>recKey(b)?-1:0;});
    const sum=el('div',{class:'dsum st-'+i.st},
      el('div',{class:'dlab'},'下次该做'),
      el('div',{class:'dbig'},i.next?showD(i.next,today,true):'完成一次后显示'),
      el('div',{class:'dline'},chipEl(i),el('span',{class:'dmeta'},freq(c)+(i.last?' · 上次 '+recText(i.last):' · 还没做过'))));
    const items=hist.length?hist.map(function(r){
      return el('li',{},
        el('span',{},showD(r.date,today,true)+(r.time?' '+r.time:'')),
        el('button',{type:'button',class:'x','aria-label':'删除 '+recText(r)+' 这条记录',onclick:function(){
          ui.err=null;
          patchChore(c.id,function(x){return Object.assign({},x,{history:(x.history||[]).filter(function(h){return h.id!==r.id;})});}).catch(fail);
        }},'×'));
    }):[el('li',{class:'none'},'还没有完成记录')];
    const bfInp=el('input',{type:'date',class:'inp','aria-label':'补记日期',value:(ui.bf&&ui.bf.date)||today,oninput:function(e){ui.bf={date:e.target.value};}});
    bfInp.max=today;
    const bfBtn=el('button',{type:'button',class:'btn',onclick:function(){
      const d=(ui.bf&&ui.bf.date)||today;
      if(!d){ui.err='请选择补记日期';redraw();return;}
      if(d>today){ui.err='补记日期不能晚于今天';redraw();return;}
      ui.bf=null;
      addRecord(c.id,{id:uid(),date:d,time:''});
    }},'补记');
    const body=el('div',{class:'body'},...kids([
      sum,errBox(),
      el('h2',{class:'sec'},'完成记录（'+hist.length+'）'),
      el('ul',{class:'hist'},...items),
      el('h2',{class:'sec'},'忘记点了？补记一天'),
      el('div',{class:'bfrow'},bfInp,bfBtn)]));
    let ft;
    if(ui.confirm==='del'){
      ft=el('div',{class:'ft wrap'},
        el('p',{class:'ask'},'删除「'+c.name+'」和它的全部记录？'),
        el('button',{type:'button',class:'btn',onclick:function(){nav({view:'detail',sel:c.id});}},'取消'),
        el('button',{type:'button',class:'btn pri',onclick:function(){
          commit(function(s){return Object.assign({},s,{chores:(s.chores||[]).filter(function(x){return x.id!==c.id;})});},
            Object.assign({},BASE,{view:'list',sel:null,draft:null})).catch(fail);
        }},'确认删除'));
    }else{
      ft=el('div',{class:'ft'},
        el('button',{type:'button',class:'btn pri grow',onclick:function(){complete(c.id);}},'完成'),
        el('button',{type:'button',class:'btn',onclick:function(){
          nav({view:'form',sel:c.id,draft:{name:c.name,n:String(c.n),unit:c.unit,date:''}});
        }},'编辑'),
        el('button',{type:'button',class:'btn',onclick:function(){ui.confirm='del';redraw();}},'删除'));
    }
    return el('div',{class:'view'},backHead(c.name,{view:'list',sel:null}),body,ft);
  }


  function formView(c){
    const d=ui.draft||(ui.draft={name:'',n:'',unit:'day',date:''});
    function save(){
      if(ui.saving)return;
      const name=String(d.name||'').trim();
      const n=Number(d.n);
      let err='';
      if(!name)err='请填写家务名称';
      else if(name.length>30)err='名称请控制在 30 个字以内';
      else if(String(d.n||'').trim()===''||!Number.isInteger(n)||n<1||n>999)err='请填写间隔：1 到 999 的整数';
      else if(!c&&d.date&&d.date>today)err='上次完成日期不能晚于今天';
      if(err){ui.err=err;redraw();return;}
      ui.err=null;ui.saving=true;redraw();
      let p;
      if(c){
        p=commit(function(s){
          return Object.assign({},s,{chores:(s.chores||[]).map(function(x){return x.id===c.id?Object.assign({},x,{name:name,n:n,unit:d.unit}):x;})});
        },Object.assign({},BASE,{view:'detail',sel:c.id,draft:null}));
      }else{
        const id=uid();
        const hist=d.date?[{id:uid(),date:d.date,time:''}]:[];
        p=commit(function(s){
          return Object.assign({},s,{chores:(s.chores||[]).concat([{id:id,name:name,n:n,unit:d.unit,history:hist}])});
        },Object.assign({},BASE,{view:'list',sel:null,draft:null,hl:id,scroll:0}));
      }
      p.catch(fail);
    }
    const nameI=el('input',{type:'text',class:'inp',value:d.name,placeholder:'例如：洗床单',oninput:function(e){d.name=e.target.value;},
      onkeydown:function(e){if(e.key==='Enter')save();}});
    const nI=el('input',{type:'number',class:'inp num',value:d.n,placeholder:'7','aria-label':'间隔数量',oninput:function(e){d.n=e.target.value;},
      onkeydown:function(e){if(e.key==='Enter')save();}});
    nI.min='1';nI.step='1';nI.setAttribute('inputmode','numeric');
    const uS=el('select',{class:'inp','aria-label':'间隔单位',onchange:function(e){d.unit=e.target.value;}},
      el('option',{value:'day'},'天'),el('option',{value:'week'},'周'),el('option',{value:'month'},'个月'));
    uS.value=d.unit||'day';
    const fields=[
      el('label',{class:'fld'},el('span',{class:'lab'},'家务名称'),nameI)];
    if(!c){
      fields.push(sugs(function(t){d.name=t;redraw();}));
    }
    fields.push(el('div',{class:'fld'},el('span',{class:'lab'},'多久做一次'),
      el('div',{class:'ivrow'},el('span',{},'每'),nI,uS)));
    if(!c){
      const dI=el('input',{type:'date',class:'inp',value:d.date||'',oninput:function(e){d.date=e.target.value;}});
      dI.max=today;
      fields.push(el('label',{class:'fld'},el('span',{class:'lab'},'上次完成日期（可选）'),dI,
        el('span',{class:'hint'},'不填：点「完成」后才开始计时。')));
    }else{
      fields.push(el('p',{class:'hint'},'修改后，下次日期会按最近一次完成重新计算。'));
    }
    const body=el('div',{class:'body'},...kids(fields.concat([errBox()])));
    const ft=el('div',{class:'ft'},
      el('button',{type:'button',class:'btn',onclick:function(){nav(c?{view:'detail',sel:c.id}:{view:'list',sel:null});}},'取消'),
      el('button',{type:'button',class:'btn pri grow',disabled:!!ui.saving,onclick:save},ui.saving?'保存中…':'保存'));
    return el('div',{class:'view'},backHead(c?'编辑家务':'添加家务',c?{view:'detail',sel:c.id}:{view:'list',sel:null}),body,ft);
  }

  const cur=ui.sel?chores.find(function(x){return x.id===ui.sel;}):null;
  if(ui.view==='detail'&&cur){
    root.appendChild(detailView(cur));
  }else if(ui.view==='form'&&(cur||!ui.sel)){
    root.appendChild(formView(cur));
  }else{
    root.appendChild(listView());
    if(listEl)listEl.scrollTop=ui.scroll||0;
  }
